      ui.showEvent('BAROMETRIC FAILURE', 'The storm is not weather. It is an invitation.');
      ui.toast('<b>NEW OBJECTIVE</b> · Find the yellow raincoat at Boulevard Park during the storm.', 'warn');
    }, 1200);
  }

